package com.energym.app.assistant;
import com.energym.app.domain.*;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public class ChatProtocolTest {
    @Test public void endpointPolicyAllowsOnlyHttpsOrDebugLoopback(){assertEquals("http://127.0.0.1:8080",HttpChatClient.endpoint("http://127.0.0.1:8080/",true));assertEquals("https://example.org",HttpChatClient.endpoint("https://example.org",false));for(String address:Arrays.asList("http://127.0.0.1:8080","http://192.168.1.2:8080","https://user:pass@example.org","https://example.org/api","https://example.org?token=private")){try{HttpChatClient.endpoint(address,false);fail(address);}catch(IllegalArgumentException expected){}}try{HttpChatClient.endpoint("http://192.168.1.2:8080",true);fail();}catch(IllegalArgumentException expected){}}
    @Test public void jsonRejectsDuplicateTrailingAndWrongTypes(){for(String json:Arrays.asList("{\"text\":1,\"text\":2}","{} {}","[NaN]","{\"x\":01}")){try{StrictJson.parse(json);fail(json);}catch(IllegalArgumentException expected){}}assertEquals("hola\n\"",StrictJson.parse(StrictJson.write("hola\n\"")));}
    @Test public void contractReplyRequiresMatchingIdsAndKnownCommands(){ChatClient.Request r=new ChatClient.Request("conv","request","squat","Explica",new TrainingProfile.Builder().build(),false,Collections.emptyList());String valid=ProposalControllerTest.validReply(r);ChatProtocol.reply(valid,r,Collections.singletonList(ProposalControllerTest.exercise("squat","Técnica")),1);for(String json:Arrays.asList(valid.replace("request","other"),valid.replace("\"commands\":[]","\"commands\":[{\"type\":\"PLAY\",\"exerciseId\":\"squat\"}]"),valid.replace("\"catalogVersion\":1","\"catalogVersion\":2"),valid.replace("\"catalogVersion\":1","\"catalogVersion\":1.0"),valid.replace("\"text\":","\"unknown\":true,\"text\":"))){try{ChatProtocol.reply(json,r,Collections.singletonList(ProposalControllerTest.exercise("squat","Técnica")),1);fail();}catch(IllegalArgumentException expected){}}}
    @Test public void prescriptionRejectsUnknownKeysExcessTimeAndExternalLoad(){Exercise e=ProposalControllerTest.exercise("squat","Técnica");Map<String,String> values=new LinkedHashMap<>(Map.of("sets","2","repetitions","8","loadKg","0","restSeconds","60"));ChatProtocol.validatePrescription(e,values,5);for(String key:Arrays.asList("unknown","loadKg","restSeconds","sets")){Map<String,String> invalid=new LinkedHashMap<>(values);invalid.put(key,key.equals("restSeconds")?"1000":key.equals("sets")?"21":"10");try{ChatProtocol.validatePrescription(e,invalid,5);fail(key);}catch(IllegalArgumentException expected){}}}
    @Test public void payloadConsentCannotBeBypassedAndNeverContainsUid(){ChatClient.Request r=new ChatClient.Request("conv","req",null,"hola",new TrainingProfile.Builder().build(),false,Collections.singletonList(new ConversationStore.Message("user","privado")));Map<String,Object> parsed=StrictJson.object(StrictJson.parse(ChatProtocol.request(r)));assertEquals(7,parsed.size());assertTrue(StrictJson.array(parsed.get("history"),12).isEmpty());assertFalse(StrictJson.object(parsed.get("profile")).containsKey("historyConsent"));assertFalse(parsed.containsKey("ownerUid"));}
}

